pm.test("All required card fields are present", function () {
    const requiredFields = [
        "id", "name", "idList", "idBoard", "idShort", "desc",
        "closed", "dueComplete", "due", "pos", "dateLastActivity",
        "shortLink", "shortUrl", "url", "labels", "idMembers", "badges"
    ];

