        (field) => jsonData[field] === undefined
    );

    pm.expect(missingFields, "Missing response fields").to.deep.equal([]);
});

pm.test("Card matches the card, list, and board from this run", function () {
    const expectedValues = {
        id: pm.variables.get("cardId"),
        name: pm.variables.get("cardName"),
        idList: pm.variables.get("listId"),
        idBoard: pm.variables.get("boardId")
    };

    Object.entries(expectedValues).forEach(([field, expectedValue]) => {
        pm.expect(expectedValue, `Expected value for ${field}`)
            .to.be.a("string").and.not.be.empty;
        pm.expect(jsonData[field], field).to.equal(expectedValue);
    });
});

pm.test("Card fields have the expected types", function () {
    pm.expect(jsonData.idShort, "Card number").to.be.a("number");
    pm.expect(jsonData.pos, "Position").to.be.a("number");
    pm.expect(jsonData.desc, "Description").to.be.a("string");
    pm.expect(jsonData.labels, "Labels").to.be.an("array");
    pm.expect(jsonData.idMembers, "Member IDs").to.be.an("array");
    pm.expect(jsonData.badges, "Badges").to.be.an("object");
    pm.expect(Date.parse(jsonData.dateLastActivity), "Last activity timestamp")
        .to.be.a("number").and.not.be.NaN;
});

pm.test("Card URLs match the returned short link", function () {
    pm.expect(jsonData.shortLink, "Short link").to.match(/^[A-Za-z0-9]+$/);

    const expectedShortUrl = `https://trello.com/c/${jsonData.shortLink}`;
    pm.expect(jsonData.shortUrl, "Short URL").to.equal(expectedShortUrl);
    pm.expect(jsonData.url, "Card URL")
        .to.satisfy((url) => url === expectedShortUrl ||
            (typeof url === "string" && url.startsWith(`${expectedShortUrl}/`)));
});

